text:
El provider queda como Client Component aislado y sincroniza Lenis con el ticker de GSAP y `ScrollTrigger.update()`:

```tsx
// app/providers/lenis-provider.tsx
"use client";

import "lenis/dist/lenis.css";

import gsap from "gsap";
import { ScrollTrigger } from "gsap/ScrollTrigger";
import { ReactLenis, type LenisRef } from "lenis/react";
import { usePathname } from "next/navigation";
import {
  type PropsWithChildren,
  useEffect,
  useRef,
} from "react";

export function LenisProvider({ children }: PropsWithChildren) {
  const lenisRef = useRef<LenisRef>(null);
  const pathname = usePathname();

  useEffect(() => {
    gsap.registerPlugin(ScrollTrigger);

    const lenis = lenisRef.current?.lenis;

    if (!lenis) {
      return;
    }

    const updateScrollTrigger = () => {
      ScrollTrigger.update();
    };

    const updateLenis = (time: number) => {
      // GSAP entrega segundos; Lenis espera milisegundos.
      lenis.raf(time * 1000);
    };

    lenis.on("scroll", updateScrollTrigger);
    gsap.ticker.add(updateLenis);
    gsap.ticker.lagSmoothing(0);

    ScrollTrigger.refresh();

    return () => {
      lenis.off("scroll", updateScrollTrigger);
      gsap.ticker.remove(updateLenis);
    };
  }, []);

  useEffect(() => {
    const frame = requestAnimationFrame(() => {
      lenisRef.current?.lenis?.resize();
      ScrollTrigger.refresh();
    });

    return () => cancelAnimationFrame(frame);
  }, [pathname]);

  return (
    <ReactLenis
      ref={lenisRef}
      root
      options={{
        autoRaf: false,
        anchors: true,
        lerp: 0.1,
        stopInertiaOnNavigate: true,
      }}
    >
      {children}
    </ReactLenis>
  );
}
```

Úsalo en el layout raíz:

```tsx
// app/layout.tsx
import { LenisProvider } from "./providers/lenis-provider";

export default function RootLayout({
  children,
}: Readonly<{
  children: React.ReactNode;
}>) {
  return (
    <html lang="es">
      <body>
        <LenisProvider>{children}</LenisProvider>
      </body>
    </html>
  );
}
```

No hace falta `ScrollTrigger.scrollerProxy()` porque `root` mantiene el scroll del documento; Lenis recomienda compartir el ticker de GSAP y convertir segundos a milisegundos. [Integración oficial de Lenis con GSAP](https://github.com/darkroomengineering/lenis/blob/main/packages/react/README.md#gsap-integration)

